package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.search.*;
import cn.mop.domain.search.GlobalSearchRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real approved local PG, existing identities, synthetic records. No source outside current tenant is searched. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresGlobalSearchIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresGlobalSearchRepository search;static String engineer,admin,viewer,tadmin,other;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(4);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);search=new PostgresGlobalSearchRepository(pool);engineer=user("服务工程师（测试身份）");admin=user("平台管理员（测试身份）");viewer=user("租户 A 只读用户（测试身份）");tadmin=user("租户 A 管理员（测试身份）");other=user("租户 B 只读用户（测试身份）");assertTrue(platform.membership(admin,OTHER).orElseThrow().active());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String user(String name){return platform.users().stream().filter(u->u.displayName().equals(name)).findFirst().orElseThrow().id();}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion());}
    static Asset asset(String tenant,String name){String key=UUID.randomUUID().toString();return (Asset)platform.idempotent(admin,tenant,"POST /integration/search/assets",key,"a".repeat(64),()->{Asset a=platform.insert(tenant,admin,name,"router","192.0.2.95",tenant.equals(TENANT)?"site-a-main":"site-b-main");platform.audit(admin,tenant,"integration.search.asset.create","asset",a.id(),"SUCCEEDED","SYNTHETIC_ONLY",key);return a;});}
    static String report(String tenant,String actor,String title,String privateText){Asset a=asset(tenant,"SEARCH-REPORT-ASSET-"+UUID.randomUUID());String key=UUID.randomUUID().toString();CustomerReportRegistration result=(CustomerReportRegistration)platform.idempotent(actor,tenant,"POST /integration/search/reports",key,"b".repeat(64),platform.membership(actor,tenant).orElseThrow().permissionVersion(),()->{var r=platform.registerCustomerReport(tenant,actor,new CustomerReport(title,privateText,"网络不通","company","合成联系人","010-12345678","urgent",a.id()));if(r.created())platform.audit(actor,tenant,"integration.search.report.create","ticket",r.ticketId(),"SUCCEEDED","SYNTHETIC_ONLY",key);return r;});return result.ticketId();}
    static Snapshot find(String actor,String query){return search.search(access(actor,TENANT),new GlobalSearchQuery(query));}
    static long audits()throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_audit")){r.next();return r.getLong(1);}}
    @Test void contractCapsAndOverflowReflectBoundedRealRows(){String marker="SEARCH-CAPS-"+UUID.randomUUID();for(int i=0;i<7;i++)asset(TENANT,marker+"-"+i);for(int i=0;i<5;i++)report(TENANT,viewer,marker+"-"+i,"合成说明");var result=find(engineer,marker);assertEquals(5,result.assets().size());assertTrue(result.moreAssets());assertEquals(3,result.tickets().size());assertTrue(result.moreTickets());assertEquals("CURRENT_TENANT_INTERNAL",result.ticketVisibility());assertNotNull(result.observedAt());assertEquals(5,result.assets().stream().map(AssetHit::id).distinct().count());assertEquals(3,result.tickets().stream().map(TicketHit::id).distinct().count());}
    @Test void customerAndTenantAdminOnlyFindOwnReports(){String marker="SEARCH-OWN-"+UUID.randomUUID();String own=report(TENANT,viewer,marker+" viewer","合成说明"),otherOwn=report(TENANT,tadmin,marker+" tadmin","合成说明");assertEquals(List.of(own),find(viewer,marker).tickets().stream().map(TicketHit::id).toList());assertEquals(List.of(otherOwn),find(tadmin,marker).tickets().stream().map(TicketHit::id).toList());assertEquals("OWN_REPORT_REGISTRATIONS",find(viewer,marker).ticketVisibility());assertEquals(Set.of(own,otherOwn),new HashSet<>(find(admin,marker).tickets().stream().map(TicketHit::id).toList()));}
    @Test void matchingForeignKeywordsNeverLeakOtherTenantObjects(){String marker="SEARCH-TENANT-"+UUID.randomUUID();Asset local=asset(TENANT,marker+" local"),foreign=asset(OTHER,marker+" foreign");String a=report(TENANT,viewer,marker+" local","合成说明"),b=report(OTHER,other,marker+" foreign","合成说明");var result=find(admin,marker);assertEquals(List.of(local.id()),result.assets().stream().map(AssetHit::id).toList());assertEquals(List.of(a),result.tickets().stream().map(TicketHit::id).toList());var reverse=search.search(access(admin,OTHER),new GlobalSearchQuery(marker));assertEquals(List.of(foreign.id()),reverse.assets().stream().map(AssetHit::id).toList());assertEquals(List.of(b),reverse.tickets().stream().map(TicketHit::id).toList());}
    @Test void unicodeRootLowerAndWildcardsAreLiteral(){String marker="SEARCH-Ä%_-"+UUID.randomUUID();Asset a=asset(TENANT,marker);String t=report(TENANT,viewer,marker,"合成说明");var result=find(engineer,marker.toLowerCase(Locale.ROOT));assertEquals(List.of(a.id()),result.assets().stream().map(AssetHit::id).toList());assertEquals(List.of(t),result.tickets().stream().map(TicketHit::id).toList());assertTrue(find(engineer,marker+"' OR '1'='1").assets().isEmpty());assertTrue(find(engineer,marker+"' OR '1'='1").tickets().isEmpty());}
    @Test void receiptSearchIsSupportedButDescriptionsAreNotQueried(){String title="SEARCH-RECEIPT-"+UUID.randomUUID(),privateText="PRIVATE-DESCRIPTION-"+UUID.randomUUID();String id=report(TENANT,viewer,title,privateText);var result=find(viewer,title);String receipt=result.tickets().get(0).receiptNo();assertEquals(List.of(id),find(viewer,receipt).tickets().stream().map(TicketHit::id).toList());assertTrue(find(viewer,privateText).tickets().isEmpty());}
    @Test void projectionContainsNoIpContactsDescriptionsOrInternalActorFields(){String marker="SEARCH-PROJECTION-"+UUID.randomUUID();asset(TENANT,marker);report(TENANT,viewer,marker,"不进入搜索结果的合成正文");var result=find(engineer,marker);var asset=mapper.valueToTree(result.assets().get(0));var ticket=mapper.valueToTree(result.tickets().get(0));assertEquals(6,asset.size());assertEquals(7,ticket.size());for(String field:List.of("managementIp","contactName","contactPhone","description","reporterId","actorId","history","attachments")){assertFalse(asset.has(field));assertFalse(ticket.has(field));}assertEquals("REGISTERED",result.tickets().get(0).registrationStatus());}
    @Test void staleMembershipAndWrongScopeRejectBeforeReturningAnyGroup(){Access a=access(engineer,TENANT);assertEquals(401,assertThrows(DomainException.class,()->search.search(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1),new GlobalSearchQuery("SEARCH"))).status);assertEquals(401,assertThrows(DomainException.class,()->search.search(new Access(viewer,OTHER,1),new GlobalSearchQuery("SEARCH"))).status);assertEquals(401,assertThrows(DomainException.class,()->search.search(new Access(UUID.randomUUID().toString(),TENANT,1),new GlobalSearchQuery("SEARCH"))).status);}
    @Test void emptyLocalMatchIsNotAnErrorAndSearchDoesNotWriteAuditOrAssets()throws SQLException{String marker="SEARCH-READONLY-"+UUID.randomUUID();Asset a=asset(TENANT,marker);long before=audits();for(int i=0;i<3;i++){var result=find(engineer,marker);assertEquals(1,result.assets().size());assertTrue(result.tickets().isEmpty());assertFalse(result.moreTickets());}assertEquals(before,audits());assertEquals(a,platform.find(TENANT,a.id()).orElseThrow());var absent=find(viewer,"ABSENT-"+UUID.randomUUID());assertTrue(absent.assets().isEmpty());assertTrue(absent.tickets().isEmpty());assertFalse(absent.moreAssets());}
    @Test void newestRegisteredAssetsAreOrderedDeterministically(){String marker="SEARCH-ORDER-"+UUID.randomUUID();List<Asset> values=new ArrayList<>();for(int i=0;i<3;i++)values.add(asset(TENANT,marker+"-"+i));List<String> ids=values.stream().sorted(Comparator.comparing(Asset::createdAt).thenComparing(Asset::id).reversed()).map(Asset::id).toList();assertEquals(ids,find(engineer,marker).assets().stream().map(AssetHit::id).toList());}
}
